import registry from "@/data/media-rights.json";

/**
 * Asset-level rights registry (generated by scripts/media/build-rights-registry.mjs).
 *
 * This module is intentionally data-only: publication is enforced by the file
 * actually living under public/ or outside it, not by a client-side flag. The
 * flags below are for UI copy and tests; they must never be treated as the
 * security boundary.
 */
export type MediaReviewStatus =
  | "pending"
  | "verified"
  | "restricted"
  | "rejected"
  | "removed";

export type MediaSourceType =
  | "wikimedia-cc0"
  | "self-authored"
  | "legacy-local-unknown"
  | "external-ai-unknown";

export interface MediaRightsRecord {
  assetId: string;
  path: string;
  privatePath: string | null;
  mime: string;
  bytes: number | null;
  sha256: string | null;
  usage: string;
  sourceType: MediaSourceType;
  sourceUrl: string | null;
  sourceFileUrl: string | null;
  sourceTitle: string | null;
  author: string | null;
  licenseType: string;
  licenseUrl: string | null;
  licenseEvidence: string | null;
  auditCheckedAt: string | null;
  auditVerified: boolean | null;
  attributionRequired: boolean | null;
  attributionText: string | null;
  modificationNotes: string;
  thirdPartyRights: string;
  aiGenerated: boolean | "unknown";
  provider?: string;
  reviewStatus: MediaReviewStatus;
  canPubliclyDisplay: boolean;
  canOfferDownload: boolean;
  publiclyAccessible: boolean;
  externalAccessible: boolean;
  parentAssetIds: string[];
  reviewedAt: string | null;
  reviewedBy: string | null;
  notes: string;
}

export const MEDIA_RIGHTS = registry.assets as MediaRightsRecord[];

export function mediaRights(assetId: string): MediaRightsRecord | undefined {
  return MEDIA_RIGHTS.find((asset) => asset.assetId === assetId);
}

/** True only for registry entries whose bytes are intentionally under public/. */
export function isPublicMediaPath(path: string): boolean {
  return MEDIA_RIGHTS.some(
    (asset) => asset.publiclyAccessible && asset.path === path
  );
}

/** Style previews are keyed as `style.<styleId>` in the registry. */
export function isStylePreviewPublic(styleId: string): boolean {
  const asset = mediaRights(`style.${styleId}`);
  return asset?.reviewStatus === "verified" && asset.canPubliclyDisplay === true;
}

/** Wallpaper downloads are permitted only for a cleared, public asset. */
export function canDownloadMediaPath(path: string | null): boolean {
  if (!path) return false;
  return MEDIA_RIGHTS.some(
    (asset) =>
      asset.path === path &&
      asset.canOfferDownload &&
      asset.publiclyAccessible
  );
}
